const JENIS_SIMPANAN_LABEL_BUKTI = {
    POKOK: 'Simpanan Pokok',
    WAJIB: 'Simpanan Wajib',
    SUKARELA: 'Simpanan Sukarela',
    BERJANGKA: 'Simpanan Berjangka',
};
/** Label jenis simpanan untuk bukti (layar & export memakai label yang sama). */
function labelJenisSimpananBukti(jenis) {
    return JENIS_SIMPANAN_LABEL_BUKTI[jenis] ?? jenis;
}
function buildBuktiBayarSimpananExport(info, item) {
    return {
        judulLaporan: 'Bukti Bayar Simpanan Anggota',
        namaFileDasar: `bukti-simpanan-${item.nomorBukti}`,
        ...info,
        periodeLabel: `${item.tanggal}`,
        kolom: ['Keterangan', 'Nilai'],
        baris: [
            ['Nomor Bukti', item.nomorBukti],
            ['Tanggal', item.tanggal],
            ['Nomor Anggota', item.nomorAnggota],
            ['Nama Anggota', item.namaAnggota],
            ['Jenis Simpanan', JENIS_SIMPANAN_LABEL_BUKTI[item.jenisSimpanan] ?? item.jenisSimpanan],
            ['Sumber Dana', item.sumberDana],
            ['Keterangan', item.keterangan ?? '-'],
        ],
        kolomAngka: [],
        ringkasan: [{ label: 'Jumlah Setoran', nilai: (0, money_1.formatRupiah)(item.jumlah) }],
    };
}
/**
 * Bukti Tarik Simpanan Anggota (§G/§W) — pola SAMA PERSIS
 * buildBuktiBayarSimpananExport, hanya arah nominalnya berbeda
 * (penarikan, bukan setoran). Untuk pencairan SIMPANAN BERJANGKA,
 * kontrak & rincian pencairannya ikut dicetak (pokok, bunga, PPh 4(2),
 * penalti, biaya administrasi) — angkanya dibaca service, tidak dihitung
 * ulang di sini.
 */
function buildBuktiTarikSimpananExport(info, item) {
    const rb = item.rincianBerjangka ?? null;
    const baris = [
        ['Nomor Bukti', item.nomorBukti],
        ['Tanggal', item.tanggal],
        ['Nomor Anggota', item.nomorAnggota],
        ['Nama Anggota', item.namaAnggota],
        ['Jenis Simpanan', labelJenisSimpananBukti(item.jenisSimpanan)],
        ['Sumber Dana', item.sumberDana],
        ['Keterangan', item.keterangan ?? '-'],
    ];
    if (rb) {
        baris.push(['Jenis Pencairan', rb.jenisPencairan === 'DINI' ? 'Penarikan Dini' : 'Pencairan Jatuh Tempo'], ['Nomor Kontrak', rb.nomorKontrak], ['Tanggal Penempatan', rb.tanggalMulai], ['Jatuh Tempo', rb.tanggalJatuhTempo], ['Tenor', `${rb.tenorBulan} bulan`], ['Suku Bunga', `${String(rb.sukuBunga).replace('.', ',')}% per tahun`]);
        if (rb.jenisPencairan === 'DINI' && rb.policyVersi)
            baris.push(['Kebijakan Penarikan Dini', `Versi ${rb.policyVersi}`]);
        baris.push(['Pokok Simpanan', (0, money_1.formatRupiah)(rb.pokok)], ['Bunga Dibayarkan', (0, money_1.formatRupiah)(rb.bunga)]);
        if (rb.pphDipotong > 0)
            baris.push(['PPh Pasal 4 ayat (2) atas Bunga', `-${(0, money_1.formatRupiah)(rb.pphDipotong)}`]);
        if (rb.penalti > 0)
            baris.push(['Penalti Penarikan Dini', `-${(0, money_1.formatRupiah)(rb.penalti)}`]);
        if (rb.biayaAdmin > 0)
            baris.push(['Biaya Administrasi', `-${(0, money_1.formatRupiah)(rb.biayaAdmin)}`]);
        if (rb.bungaHangus > 0)
            baris.push(['Bunga Hangus (tidak dibayarkan)', (0, money_1.formatRupiah)(rb.bungaHangus)]);
    }
    return {
        judulLaporan: 'Bukti Tarik Simpanan Anggota',
        namaFileDasar: `bukti-tarik-simpanan-${item.nomorBukti}`,
        ...info,
        periodeLabel: `${item.tanggal}`,
        kolom: ['Keterangan', 'Nilai'],
        baris,
        kolomAngka: [],
        ringkasan: [{ label: rb ? 'Total Diterima Anggota' : 'Jumlah Penarikan', nilai: (0, money_1.formatRupiah)(item.jumlah) }],
    };
}
