    const hasilUsahaPeriode = posisiAkhir.labaBerjalan;
    const hasilUsahaPeriodeLabel = posisiAkhir.labaBerjalanLabel;
    // RC-S133.6 (AUDIT F-4) — KESINAMBUNGAN ANTAR-TAHUN, TANPA closing entry.
    //
