        tanggalMulai,
        tanggalSelesai,
        rows,
        totalSaldoAwal,
        totalMutasi,
        hasilUsahaPeriode,
        hasilUsahaPeriodeLabel,
        totalSaldoAkhir,
        saldoAwalHasilUsaha,
        hasilUsahaPeriodeBerjalan,
        shuDibagikanPeriode,
        lhuPeriode,
