/** Label kolom yang dipakai ilustrasi — untuk test "panduan tidak menyebut kolom yang tidak ada". */
function kolomIlustrasi(slides) {
    const out = [];
    for (const s of slides) {
        if (s.ilustrasi.jenis !== 'SHEET')
            continue;
        for (const k of s.ilustrasi.kolom)
            out.push({ sheet: s.ilustrasi.tabAktif, kolom: k });
    }
    return out;
}
/** True bila kolom ilustrasi wajib menurut template (untuk tanda * pada ilustrasi). */
function kolomWajibIlustrasi(sheet, kolom) {
    if (sheet === ExcelDataAwalParser_1.JUDUL_SHEET_SALDO_AWAL_AKUN)
        return kolom === 'Kode Akun' || kolom === 'Saldo';
    return wajib(sheet, kolom);
}
